import { describe, expect, it } from 'vitest';

import { SYSTEM_PROMPT } from '../src/ai/prompt.js';

/**
 * The approval prompt is generated by the **server**, not by the model.
 *
 * The model has to call a consequential tool; the server then parks the
 * run and asks the user. A prompt that lets the model satisfy the
 * instruction by *talking* instead of calling produces an agent that
 * says "shall I create that branch?" and does nothing — which is what a
 * live model did with the previous wording.
 */
describe('the system prompt tells the model to call, not to ask', () => {
  it('says the server raises the approval prompt', () => {
    expect(SYSTEM_PROMPT).toContain('CALL it');
    expect(SYSTEM_PROMPT).toMatch(/server stops the run/i);
  });

  it('forbids asking for confirmation in the reply', () => {
    // The prompt is a wrapped template literal, so the phrases are matched
    // across line breaks.
    expect(SYSTEM_PROMPT).toMatch(/never ask for\s+confirmation/i);
  });

  it('does not invite the model to announce a destructive action instead', () => {
    // The old wording ("say in one short sentence what you are about to
    // do and why") is what let the model talk instead of acting.
    expect(SYSTEM_PROMPT).not.toMatch(/say in one short sentence/i);
  });

  it('still tells the model to read tool results and never fabricate one', () => {
    expect(SYSTEM_PROMPT).toMatch(/call the tool instead of guessing/i);
    expect(SYSTEM_PROMPT).toMatch(/never fabricate/i);
  });
});
